package eu.jodelahithit;

import java.util.Set;

public enum NotificationType {
    NONE(null, null),
    COOKING(Constants.COOKING_ANIMATIONS, null),
    CRAFTING(Constants.CRAFTING_ANIMATIONS, null),
    FISHING(Constants.FISHING_ANIMATIONS, null),
    FIREMAKING(Constants.FIREMAKING_ANIMATIONS, null),
    FLETCHING(Constants.FLETCHING_ANIMATIONS, null),
    HERBLORE(Constants.HERBLORE_ANIMATIONS, null),
    MINING(Constants.MINING_ANIMATIONS, null),
    WOODCUTTING(Constants.WOODCUTTING_ANIMATIONS, null),
    SMITHING(Constants.SMITHING_ANIMATIONS, null),
    SAILING(Constants.SAILING_ANIMATIONS, null),
    MANIACALMONKEYS(Constants.MONKEY_ANIMS, "/eu/jodelahithit/monkey.png"),
    LUNAR(Constants.LUNAR_ANIMATIONS, "/eu/jodelahithit/lunar.png"),
    COMBAT(null, null),
    CUSTOMXP(null, null);


    private final Set<Integer> animations;
    private final String customImage;

    NotificationType(Set<Integer> animations, String customImage) {
        this.animations = animations;
        this.customImage = customImage;
    }

    public Set<Integer> getAnimations() {
        return animations;
    }

    public String getCustomImage() {
        return customImage;
    }

    boolean matchesAnimation(int animation) {
        return animations != null && animations.contains(animation);
    }
}

package eu.jodelahithit;

import java.util.concurrent.TimeUnit;

public class Session {
    private static final long BASE_SKILL_DELAY_MS = 500L;
    private static final long SAILING_DELAY_MS = 2000L;

    private final long[] skillActiveUntil = new long[NotificationType.values().length];

    private final SkillingNotificationsPlugin plugin;

    private long walkingUpdatedAt = System.nanoTime();
    private long sailingUpdatedAt = System.nanoTime();

    public Session(SkillingNotificationsPlugin plugin) {
        this.plugin = plugin;
    }

    public void updateInstant(NotificationType type) {
        long delayMs = BASE_SKILL_DELAY_MS + Math.max(plugin.getExtraSkillDelay(type), 0);
        skillActiveUntil[type.ordinal()] = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(delayMs);
    }

    public boolean isSkillActive(NotificationType type) {
        return skillActiveUntil[type.ordinal()] - System.nanoTime() > 0;
    }

    public void updateWalkingInstant() {
        walkingUpdatedAt = System.nanoTime();
    }

    public void updateSailingInstant() {
        sailingUpdatedAt = System.nanoTime();
    }


    public boolean isWalking(long extraTimeoutMs) {
        long elapsed = System.nanoTime() - walkingUpdatedAt;
        long timeout = TimeUnit.MILLISECONDS.toNanos(
                1L + Math.max(extraTimeoutMs, 0)
        );

        return elapsed < timeout;
    }

    public boolean isSailing() {
        long elapsed = System.nanoTime() - sailingUpdatedAt;
        return elapsed < TimeUnit.MILLISECONDS.toNanos(SAILING_DELAY_MS);
    }
}

